<template><article class="rounded-xl border border-base-200 p-4"><h3 class="text-sm font-bold">{{ title }}</h3><div class="mt-2 flex flex-wrap gap-1"><span v-if="decision" class="badge badge-sm badge-primary">{{ label(decision) }}</span><span v-if="directive" class="badge badge-sm badge-outline">{{ label(directive) }}</span></div><p class="mt-3 whitespace-pre-line text-sm text-base-content/70">{{ comments || 'Pending review' }}</p></article></template>
<script setup>defineProps({ title: String, decision: String, directive: String, comments: String }); const label = value => String(value || '').replaceAll('_', ' ').toLowerCase().replace(/\b\w/g, c => c.toUpperCase());</script>
